for update

mapper.update:
update sdsshop.u_m_stocktake
   set status = #{toStatus},

       submit_user = #{username},
       submit_time = sysdate(),


       reject_reason = #{rejectReason},

       update_time = sysdate()
 where shop_code = #{shopCode}
   and stocktake_code = #{stocktakeCode}
   and status = #{fromStatus}

update sdsshop.u_m_stocktake
   set line_count = (select count(*) from sdsshop.u_m_stocktake_item i
                      where i.shop_code = #{shopCode} and i.stocktake_code = #{stocktakeCode}),
       update_time = sysdate()
 where shop_code = #{shopCode}
   and stocktake_code = #{stocktakeCode}

update sdsshop.u_m_stocktake_item
   set counted_qty = #{countedQty},
       cost_price = #{costPrice},
       batch_code = #{batchCode},
       serial_nos = #{serialNos},
       remark = #{remark},
       update_time = sysdate()
 where shop_code = #{shopCode}
   and stocktake_code = #{stocktakeCode}
   and id = #{id}

update sdsshop.u_m_stocktake_item
   set book_qty = #{bookQty},
       diff_qty = #{diffQty},
       diff_amount = #{diffAmount},
       update_time = sysdate()
 where shop_code = #{shopCode}
   and stocktake_code = #{stocktakeCode}
   and id = #{id}

mapper.delete:
delete from sdsshop.u_m_stocktake_item
 where shop_code = #{shopCode}
   and stocktake_code = #{stocktakeCode}
   and id = #{id}

mapper.select:
select i.id, i.shop_code, i.stocktake_code, i.goods_code, i.goods_name, i.spec, i.unit, i.qualityflag, i.book_qty, i.counted_qty, i.diff_qty, i.cost_price, i.diff_amount, i.batch_code, i.serial_nos, i.remark, null as batchstrategy, null as costcalculation, null as current_qty, null as locked_qty from sdsshop.u_m_stocktake_item i join sdsshop.u_m_stocktake t on t.shop_code = i.shop_code and t.stocktake_code = i.stocktake_code where i.shop_code = #{shopCode} and t.ware_code = #{wareCode} and t.status in ('盘点中', '待审核')
and t.stocktake_code != #{excludeStocktakeCode}
and i.goods_code in
#{code}
order by i.goods_code
